import * as THREE from 'three';
import calibration from './seasonal-light.json';
import type { Season } from './season';

// Paired Cycles reference measurements, generated by bake_seasonal_probes.py.
// Grid-wide RGB energy changes retain the original angular SH and occlusion.
// Summer is exactly neutral. Once a season's rebake of the outdoor grids has arrived
// (seasonalProbes.ts), those grids hold the season themselves and their gains are 1; the room and
// water grids keep the calibrated gains. suiSeasonDeck keeps the calibrated courtyard irradiance of
// the evening and night for the summer-baked stepping-stone light (deckIrradiance.ts).
const GRID_COUNT = 4;
const REBAKED_GRIDS = [1, 2];

export function createSeasonLightUniforms() {
  return {
    suiSeasonIrradiance: { value: Array.from({ length: 12 }, () => new THREE.Vector3(1, 1, 1)) },
    suiSeasonReflection: { value: Array.from({ length: 12 }, () => new THREE.Vector3(1, 1, 1)) },
    suiSeasonDeck: { value: Array.from({ length: 2 }, () => new THREE.Vector3(1, 1, 1)) },
  };
}

type Uniforms = ReturnType<typeof createSeasonLightUniforms>;
const painted = new WeakMap<Uniforms, string>();

/** Updates the existing uniform objects before a draw, including warmup/mirror draws. */
export function updateSeasonLight(uniforms: Uniforms, season: Season, rebaked = false) {
  const key = `${season}/${rebaked}`;
  if (painted.get(uniforms) === key) return false;
  for (const [kind, uniform] of [
    ['irradiance', uniforms.suiSeasonIrradiance],
    ['reflection', uniforms.suiSeasonReflection],
  ] as const) {
    for (let i = 0; i < uniform.value.length; i++) {
      const grid = Math.floor((i * GRID_COUNT) / uniform.value.length);
      if (season === 'summer' || (rebaked && REBAKED_GRIDS.includes(grid))) uniform.value[i].set(1, 1, 1);
      else uniform.value[i].fromArray(calibration.gains[season][kind][i]);
    }
  }
  uniforms.suiSeasonDeck.value.forEach((gain, i) =>
    season === 'summer' ? gain.set(1, 1, 1) : gain.fromArray(calibration.gains[season].irradiance[4 + i]),
  );
  painted.set(uniforms, key);
  return true;
}
